`timescale 1ns/1ps

// Deterministic digital RGB rendering of NES 2C02 color numbers. The base
// table is the NESdev 2C02G reference palette generated by Pally. Emphasis is
// an intentionally digital approximation: each asserted emphasis bit keeps
// its named channel and attenuates the other two channels by 25 percent.
module nes_palette_rgb (
    input  logic [5:0] nes_color,
    input  logic [2:0] emphasis,
    output logic [7:0] red,
    output logic [7:0] green,
    output logic [7:0] blue
);
    logic [23:0] base_rgb;
    logic [7:0] base_red;
    logic [7:0] base_green;
    logic [7:0] base_blue;

    function automatic logic [7:0] attenuate(input logic [7:0] value);
        attenuate = (value >> 1) + (value >> 2);
    endfunction

    always_comb begin
        case (nes_color)
            6'h00: base_rgb = 24'h626262;
            6'h01: base_rgb = 24'h001c95;
            6'h02: base_rgb = 24'h1904ac;
            6'h03: base_rgb = 24'h42009d;
            6'h04: base_rgb = 24'h61006b;
            6'h05: base_rgb = 24'h6e0025;
            6'h06: base_rgb = 24'h650500;
            6'h07: base_rgb = 24'h491e00;
            6'h08: base_rgb = 24'h223700;
            6'h09: base_rgb = 24'h004900;
            6'h0a: base_rgb = 24'h004f00;
            6'h0b: base_rgb = 24'h004816;
            6'h0c: base_rgb = 24'h00355e;
            6'h0d: base_rgb = 24'h000000;
            6'h0e: base_rgb = 24'h000000;
            6'h0f: base_rgb = 24'h000000;
            6'h10: base_rgb = 24'hababab;
            6'h11: base_rgb = 24'h0c4edb;
            6'h12: base_rgb = 24'h3d2eff;
            6'h13: base_rgb = 24'h7115f3;
            6'h14: base_rgb = 24'h9b0bb9;
            6'h15: base_rgb = 24'hb01262;
            6'h16: base_rgb = 24'ha92704;
            6'h17: base_rgb = 24'h894600;
            6'h18: base_rgb = 24'h576600;
            6'h19: base_rgb = 24'h237f00;
            6'h1a: base_rgb = 24'h008900;
            6'h1b: base_rgb = 24'h008332;
            6'h1c: base_rgb = 24'h006d90;
            6'h1d: base_rgb = 24'h000000;
            6'h1e: base_rgb = 24'h000000;
            6'h1f: base_rgb = 24'h000000;
            6'h20: base_rgb = 24'hffffff;
            6'h21: base_rgb = 24'h57a5ff;
            6'h22: base_rgb = 24'h8287ff;
            6'h23: base_rgb = 24'hb46dff;
            6'h24: base_rgb = 24'hdf60ff;
            6'h25: base_rgb = 24'hf863c6;
            6'h26: base_rgb = 24'hf8746d;
            6'h27: base_rgb = 24'hde9020;
            6'h28: base_rgb = 24'hb3ae00;
            6'h29: base_rgb = 24'h81c800;
            6'h2a: base_rgb = 24'h56d522;
            6'h2b: base_rgb = 24'h3dd36f;
            6'h2c: base_rgb = 24'h3ec1c8;
            6'h2d: base_rgb = 24'h4e4e4e;
            6'h2e: base_rgb = 24'h000000;
            6'h2f: base_rgb = 24'h000000;
            6'h30: base_rgb = 24'hffffff;
            6'h31: base_rgb = 24'hbee0ff;
            6'h32: base_rgb = 24'hcdd4ff;
            6'h33: base_rgb = 24'he0caff;
            6'h34: base_rgb = 24'hf1c4ff;
            6'h35: base_rgb = 24'hfcc4ef;
            6'h36: base_rgb = 24'hfdcace;
            6'h37: base_rgb = 24'hf5d4af;
            6'h38: base_rgb = 24'he6df9c;
            6'h39: base_rgb = 24'hd3e99a;
            6'h3a: base_rgb = 24'hc2efa8;
            6'h3b: base_rgb = 24'hb7efc4;
            6'h3c: base_rgb = 24'hb6eae5;
            6'h3d: base_rgb = 24'hb8b8b8;
            6'h3e: base_rgb = 24'h000000;
            default: base_rgb = 24'h000000;
        endcase

        base_red = base_rgb[23:16];
        base_green = base_rgb[15:8];
        base_blue = base_rgb[7:0];

        red = (emphasis[1] || emphasis[2]) ? attenuate(base_red) : base_red;
        green = (emphasis[0] || emphasis[2]) ? attenuate(base_green) :
                                               base_green;
        blue = (emphasis[0] || emphasis[1]) ? attenuate(base_blue) : base_blue;
    end
endmodule
